data = read('/input/data')
nodes = data['nodes']
edges = data['edges']
start = data['start']
dist = {}
for n in nodes:
    dist = putmap(dist,n,-1)
dist = putmap(dist,start,0)
remaining = list(nodes)
while len(remaining) > 0:
    reachable = [n for n in remaining if get(dist,n,-1) >= 0]
    if len(reachable) == 0:
        break
    current = min(reachable,key=lambda n:get(dist,n,-1))
    remaining = [n for n in remaining if n != current]
    for e in edges:
        if e['u'] == current:
            nd = get(dist,current,-1) + e['weight']
            if get(dist,e['v'],-1) < 0 or nd < get(dist,e['v'],-1):
                dist = putmap(dist,e['v'],nd)
main = [{'id':n,'distance':get(dist,n,-1)} for n in sorted(nodes)]
